{
  "world_name": "埃诺克",
  "realms": [
    {
      "name": "灰林边境地",
      "summary": "王国东北部的一片广阔丘陵与森林交错的区域，因秋日常见的灰色雾气而得名，王室法令在此地效力甚微。"
    }
  ],
  "factions": [
    {
      "name": "法尔肯堡伯爵领",
      "summary": "名义上统治灰林边境地的世袭贵族，专注于城堡内的奢华生活与领地核心区域的税收，对边远地区的控制力薄弱。",
      "location": "位于灰林边境地的中心地带，南部与王国腹地接壤，北部和东部则深入无主之地。"
    },
    {
      "name": "圣光教会",
      "summary": "在王国境内拥有巨大影响力的宗教组织，通过散布在各地的教堂与神父，为民众提供精神慰藉与有限的物质援助。",
      "location": "势力遍布整个王国，在灰林边境地的每一个村镇都设有教堂或礼拜堂。"
    },
    {
      "name": "黑狼佣兵团",
      "summary": "活跃于灰林边境地的一支著名佣兵团体，接受任何出价合理的雇佣，以凶悍和不守规矩闻名。",
      "location": "没有固定据点，通常在边境地北部的各个酒馆和城镇间流窜，寻找生意。"
    }
  ]
}
{
  "name": "白溪谷地",
  "parent_realm": "灰林边境地",
  "summary": "一片被森林环绕的宁静河谷，土地肥沃，民风淳朴。此地因缺乏矿产和战略价值而被领主忽视，居民依靠农业和林业自给自足。",
  "figures": [],
  "locations": [
    {
      "name": "橡木村",
      "summary": "谷地中最大的聚落，村民们在此世代农耕，村中心有一口老井和一小片公共市场。"
    },
    {
      "name": "圣劳伦斯教堂",
      "summary": "位于橡木村旁的小教堂，由石头和木材建成，是村民进行祈祷和集会的场所。"
    },
    {
      "name": "鸦巢堡",
      "summary": "建在谷地东侧山脊上的一座废弃哨塔，视野开阔，易守难攻，现已被盗匪占据作为巢穴。"
    },
    {
      "name": "石桥镇",
      "summary": "位于谷地以南一日路程的小镇，有一座横跨白溪的古老石桥，是周边地区唯一的贸易集市。"
    }
  ]
}
[
  {
    "name": "鸦巢堡",
    "parent_area": "白溪谷地",
    "summary": "一座占据废弃哨塔改造而成的山寨，是主角势力的核心据点。堡垒居高临下，控制着谷地东侧的唯一通道，内部经过初步修缮，正在逐步建立秩序。",
    "points_of_interest": [
      {
        "name": "聚义厅",
        "summary": "由原哨塔底层大厅改造而成，用于议事、宴饮和分配战利品。"
      },
      {
        "name": "简易工坊",
        "summary": "用于修理武器、盔甲和制作简易工具的区域，由具备手艺的成员负责。"
      },
      {
        "name": "瞭望台",
        "summary": "哨塔的顶层，提供绝佳的视野，用于监视谷地内外的动向。"
      }
    ],
    "figures": [
      {
        "name": "主角",
        "summary": "鸦巢堡的新主人，正在努力整合手下，试图在这片混乱的土地上站稳脚跟。"
      }
    ]
  },
  {
    "name": "橡木村",
    "parent_area": "白溪谷地",
    "summary": "一个被古老橡树林环绕的宁静村庄，村民以种植白溪谷地特有的小麦为生。村庄的建筑多为木石结构，充满了朴素的乡土气息。",
    "points_of_interest": [
      {
        "name": "圣劳伦斯教堂",
        "summary": "村庄的精神中心，一座小而古朴的石砌教堂，老神父在此主持弥撒，圣女也居住于此。"
      },
      {
        "name": "村长木屋",
        "summary": "村长的住所，也是村民们商议村内事务的非正式集会点。"
      },
      {
        "name": "公共水井",
        "summary": "村庄中心的水源地，是村民们日常取水和交流信息的重要场所。"
      }
    ],
    "figures": [
      {
        "name": "圣女",
        "summary": "居住在教堂的年轻女孩，因能展现微弱的神术而深受村民爱戴，正为村庄的困境而忧心。"
      },
      {
        "name": "老神父",
        "summary": "圣劳伦斯教堂的管理者，圣女的引导者，一位慈祥且知识渊博的长者。"
      }
    ]
  }
]

